{"additions":45,"deletions":0,"filename":"[REDACTED].xhtml","patch":"@@ -0,0 +1,45 @@
+<html xmlns="http://www.w3.org/1999/xhtml"
+      xmlns:h="http://xmlns.jcp.org/jsf/html"
+      xmlns:f="http://xmlns.jcp.org/jsf/core"
+      xmlns:p="http://primefaces.org/ui">
+<f:metadata>
+    <f:viewParam name="trackingId"
+                 value="#{changeArrivalDeadlineDate.trackingId}"/>
+    <f:viewAction action="#{changeArrivalDeadlineDate.load}"/>
+</f:metadata>
+<h:head>
+    <title>Change Deadline</title>
+</h:head>
+<h:body>
+    <div class="ui-g full-page">
+        <h:form id="changeArrivalDeadlineDateForm">
+            <p:messages id="messages" showDetail="false"/>
+            <h:panelGrid columns="2" cellpadding="15">
+                <p:outputLabel value="Origin:" />
+                <p:outputLabel value="#{changeArrivalDeadlineDate.cargo.originName}"/>
+
+                <p:outputLabel value="Destination:"/>
+                <p:outputLabel value="#{changeArrivalDeadlineDate.cargo.finalDestinationName}"/>
+
+                <p:outputLabel for="arrivalDeadlineDate" value="Deadline:"/>
+                <h:panelGroup>
+                    <p:datePicker id="arrivalDeadlineDate"
+                                  value="#{changeArrivalDeadlineDate.arrivalDeadlineDate}"
+                                  pattern="MM/dd/yyyy"
+                                  required="true"
+                                  requiredMessage="Arrival deadline date is required."/>
+                    <p:message for="arrivalDeadlineDate"/>
+                </h:panelGroup>
+
+                <p:commandButton value="Cancel" process="@this"
+                                 action="#{changeArrivalDeadlineDateDialog.cancel()}"/>
+
+                <p:commandButton value="Update"
+                                 action="#{changeArrivalDeadlineDate.changeArrivalDeadline()}"
+                                 update="@form"
+                                 oncomplete="if (args &amp;&amp; !args.validationFailed) window.location.replace(window.location.href);"/>
+            </h:panelGrid>
+        </h:form>
+    </div>
+</h:body>
+</html>","status":"added"}

